<span class="line">        <span class="token keyword">this</span><span class="token punctuation">.</span>onFulfilledCallbacks<span class="token punctuation">.</span><span class="token function">push</span><span class="token punctuation">(</span>handleFulfilled<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
