<span class="line">      element<span class="token punctuation">.</span><span class="token function">removeEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;touchmove&#39;</span><span class="token punctuation">,</span> onTouchMove<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
